      credit:
        "Roster, Stufengrenzen, Stufen-Bilder und Stufen-Tabellen von der Pop-Epoch-Wiki-Seite Buildings (Fandom), zuletzt zusammengeführt am 18. September 2026. Produktions-Ressourcentypen und Prioritätssterne aus einer Community-Discord-Liste; Aufklärung dank Spitzell. Produktions-Ausschnitte aus deutschen Client-Screenshots vom 16. September 2026. Die Bilder gehören dem Publisher des Spiels.",
