      summary: "Prioritäten für Endless Floor und wann Bonus-Area-Edelsteine sich lohnen.",
      intro:
        "Eine praktische Reihenfolge für Atlantis Endless Floor und ein kurzer Hinweis zu zusätzlichen Bonus-Area-Versuchen.",
